import{z as o,x as s,o as l,c as m,q as B,j as i,D as E,d as e,s as A,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"多语言与区域化收束","description":"","frontmatter":{"title":"多语言与区域化收束","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ml-map.md","filePath":"llm/ml-map.md","lastUpdated":1791063341000}'),p={name:"llm/ml-map.md"};function d(D,a,f,h,c,u){const r=s("Mermaid");return l(),m("div",null,[a[2]||(a[2]=B('<h1 id="多语言与区域化收束" tabindex="-1">多语言与区域化收束 <a class="header-anchor" href="#多语言与区域化收束" aria-label="Permalink to &quot;多语言与区域化收束&quot;">​</a></h1><div class="epigraph"><p>多语言与区域化的产出不是一张覆盖地图，而是一套花钱看得见的顺序：切法、迁移、数据、卷面、变体、规范、法律。</p><footer>—— 据本课程各课口径整理</footer></div><p><a href="/llm/ml-regional-compliance">上一课</a>把硬约束收进流水线：区域判定、政策分层、审计留痕。至此零件齐了：语言侧三课管「模型怎么吃进与生成这门语言」，区域侧四课管「这门语言的用户拿到什么质量与什么边界」。本课把它们装配成一张上线地图与一张决策单。<strong>本课程到此收束。</strong></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>上线一门新语言或新区域时，决策散在七处：词表与正则要不要动、零样本够不够、数据从哪补、评测卷怎么建、变体怎么分层、规范怎么适配、法律怎么映射。各自局部最优会互相拆台：不先审 fertility 就上原生评测卷，碎片化会把编码损失写成能力差距；不先建原生卷就调文化层，调的是噪声；不先做合规映射就定产品边界，返工的是整个拒答策略。收束要给的是先后顺序与跨语言不动的不变量。</p><p><span class="marginnote">fertility（碎片率）翻译过来就是「同样一句话，目标语言要切的块数是英语的几倍」。数字实例：某语言 fertility 为 2.0，意味着中文一句 50 个 token 的意思在它那里要 100 个 token——上下文窗口的有效容量、按 token 计费的成本、生成延迟都近似翻倍，而且这纯粹是切法问题，模型能力再强也省不掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>决策单七步，按依赖排序。第一步分词审计：用<a href="/llm/ml-tokenizer-multilingual">多语言分词的工程</a>的 fertility 表与回退率，决定名额与正则要不要动。第二步迁移诊断：<a href="/llm/ml-crosslingual-transfer">跨语言迁移</a>的零样本基线加思维链语言选择实验，判断干预强度。第三步数据获取：<a href="/llm/ml-low-resource">低资源语言</a>的三条路径按档位配比，进台账。第四步原生卷：<a href="/llm/ml-multilingual-eval">多语言评测</a>的三卷流水线，作答语言一致性与判卷本地化随分数发布。第五步变体分层：<a href="/llm/ml-dialect-accent">方言与口音</a>的谱系采样，分列与最坏值。第六步规范层：<a href="/llm/ml-cultural-alignment">文化对齐</a>的三层分离与区域注入。第七步合规映射：<a href="/llm/ml-regional-compliance">区域合规与本地化</a>的谓词表与留痕。</p><p>每步的输出是下一步的输入：fertility 表决定评测分数怎么解读；迁移诊断决定数据预算往哪花；合规映射决定产品边界的最外圈。倒着做，每一步的归因都会被上一步的欠账污染。</p><p><span class="marginnote">多语言上线与单语言上线的默认风险不同：平均分会掩饰一切。七步中任何一步的欠账——碎片化、数据稀、判卷偏置、口音差距——都集中兑现在尾部语言与边缘变体上，所以每一步都看最坏值，不看均值。</span></p>',10)),(l(),i(n,null,{default:E(()=>[A(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%88%86%E8%AF%8D%E5%AE%A1%E8%AE%A1%22%5D%20--%3E%20B%5B%22%E8%BF%81%E7%A7%BB%E8%AF%8A%E6%96%AD%22%5D%0A%20%20B%20--%3E%20C%5B%22%E6%95%B0%E6%8D%AE%E8%8E%B7%E5%8F%96%E4%B8%8E%E9%85%8D%E6%AF%94%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%8E%9F%E7%94%9F%E8%AF%84%E6%B5%8B%E5%8D%B7%22%5D%0A%20%20D%20--%3E%20E%5B%22%E5%8F%98%E4%BD%93%E5%88%86%E5%B1%82%E8%AF%84%E6%B5%8B%22%5D%0A%20%20E%20--%3E%20F%5B%22%E5%8C%BA%E5%9F%9F%E8%A7%84%E8%8C%83%E5%B1%82%22%5D%0A%20%20F%20--%3E%20G%5B%22%E5%90%88%E8%A7%84%E6%98%A0%E5%B0%84%E4%B8%8E%E7%95%99%E7%97%95%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"七步之下有四条跨语言不动的不变量。第一，分列报告：任何多语言分数不做单标量平均，尾部语种与最坏值必须可见——被平均掉的就是最需要看见的。第二，原生卷优先：译文卷测迁移，原生卷测该语言世界；覆盖声明止于已测语言。第三，变体与规范是谱系：语言内部不均匀，文化不等于国籍；分层采样与默认值语义替代二元清单。第四，硬软分层：文化规范可实验、可灰度，法律谓词走评审与版本冻结；两层共用注入机制但更新流程分离——合规错误与文化错误的代价不同，流程必须不同。这四条不变量与单语言对齐工程里的成对报告、政策先行同构：尺度换了，审计结构不换。",-1)),(l(),i(n,null,{default:E(()=>[A(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20INV%5B%22%E5%9B%9B%E6%9D%A1%E4%B8%8D%E5%8F%98%E9%87%8F%22%5D%20--%3E%20I1%5B%22%E5%88%86%E5%88%97%E6%8A%A5%E5%91%8A%22%5D%0A%20%20INV%20--%3E%20I2%5B%22%E5%8E%9F%E7%94%9F%E5%8D%B7%E4%BC%98%E5%85%88%22%5D%0A%20%20INV%20--%3E%20I3%5B%22%E8%B0%B1%E7%B3%BB%E4%BB%A3%E6%9B%BF%E6%B8%85%E5%8D%95%22%5D%0A%20%20INV%20--%3E%20I4%5B%22%E7%A1%AC%E8%BD%AF%E5%88%86%E5%B1%82%22%5D%0A%20%20I1%20--%3E%20P1%5B%22%E9%98%B2%E6%AD%A2%EF%BC%9A%E5%B9%B3%E5%9D%87%E5%88%86%E6%B7%B9%E6%B2%A1%E5%B0%BE%E9%83%A8%E8%AF%AD%E7%A7%8D%22%5D%0A%20%20I2%20--%3E%20P2%5B%22%E9%98%B2%E6%AD%A2%EF%BC%9A%E8%AF%91%E6%96%87%E5%8D%B7%E9%AB%98%E5%88%86%E8%AF%AF%E5%BD%93%E8%AF%AD%E8%A8%80%E8%83%BD%E5%8A%9B%22%5D%0A%20%20I3%20--%3E%20P3%5B%22%E9%98%B2%E6%AD%A2%EF%BC%9A%E4%BA%8C%E5%85%83%E6%B8%85%E5%8D%95%E5%88%87%E4%B8%A2%E8%BE%B9%E7%BC%98%E5%8F%98%E4%BD%93%22%5D%0A%20%20I4%20--%3E%20P4%5B%22%E9%98%B2%E6%AD%A2%EF%BC%9A%E5%90%88%E8%A7%84%E5%8F%98%E6%9B%B4%E8%B5%B0%E5%AE%9E%E9%AA%8C%E7%81%B0%E5%BA%A6%E9%85%BF%E6%88%90%E4%BA%8B%E6%95%85%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=B('<p><span class="marginnote">七步与四不变量的关系可以这样记：七步是流程图，回答「先做什么后做什么」；不变量是盖在每个环节上的检验章，回答「这一步做完怎样才算合格」。流程可以按项目裁剪，检验章在哪个版本里都不能撕——初学者容易只抄流程、跳过检验，结果每步「做完了」但归因全被污染。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>这张地图的适用边界要诚实。其一，它是工程顺序，不是能力承诺：七步走完不保证质量，只保证每一步的归因干净——分得清编码损失、知识缺口、规范错位与法律约束。其二，路线级替代在地图之上：字节级模型绕开词表名额之争，翻译管道把跨语言问题外包给机器翻译，区域专训小模型用局部换全局；选型先于七步，而不是七步代替选型。其三，语言与区域都在移动：正字法在标准化、法规在分阶段生效、社区在争取命名权；地图要带版本号重跑，不是一次测绘终身使用。</p><p><span class="marginnote">常见误区：把「七步走完」当成「我们支持这门语言了」。走完七步保证的只是每一步的归因干净——你分得清问题是出在切法、数据、判卷还是法律，但质量本身行不行，要拿分列的最坏值说话。可以类比体检流程：走完所有检查项目不等于身体健康，只等于你拿到了一份不会被误读的报告。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>上线顺序七步：分词 → 迁移 → 数据 → 原生卷 → 变体 → 规范 → 合规；依赖方向不可倒。</li><li>四条不变量：分列报告、原生卷优先、谱系代替清单、硬软分层。</li><li>每步产出是下一步的输入；归因干净比分数好看更根本。</li><li>字节级、翻译管道、区域小模型是路线级替代，选型在地图之上。</li><li>语言与区域都在移动；地图带版本重跑，覆盖声明止于已测。</li><li>出处：Conneau et al., 2020；Shi et al., ICLR 2023；Team NLLB, 2022；Joshi et al., ACL 2020；Koenecke et al., PNAS 2020；Hofstede, 2001；GDPR 与 EU AI Act 官方文本，按本课程整理。</li></ul>',6))])}const C=o(p,[["render",d]]);export{_ as __pageData,C as default};
